#!/usr/bin/env python3
"""Generates src/decoders/modern/aac/sauti_aac_ssr_tables.c: the DATA of the AAC SSR (AOT 3) tools that cannot be derived from a formula, taken from the ISO/IEC 14496-5 reference software
(C050470e_Electronic_inserts/audio/natural/aacErrRobTrans: gc_pqf_common.c = the 48 free coefficients of the 96-tap prototype of the polyphase quadrature filter bank, decdata.c = the SSR columns
of TNS_MAX_BANDS).  The licence notice of that software is in third_party/iso14496-5/NOTICE and in the generated file; the code of the SSR tools in Sauti is written for Sauti (the KBD windows
are computed, they are not tables).  usage: tools/gen_aac_ssr_tables.py [DIR_aacErrRobTrans]   (default ~/tmp_ayo/tmp/iso_ref/x/C050470e_Electronic_inserts/audio/natural/aacErrRobTrans; read-only)"""
import os, re, sys
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
D = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/tmp_ayo/tmp/iso_ref/x/C050470e_Electronic_inserts/audio/natural/aacErrRobTrans')
pq = open(os.path.join(D, 'gc_pqf_common.c'), encoding='latin-1').read()
m = re.search(r'a_half\[48\]\s*=\s*\{(.*?)\};', pq, re.S); half = [x for x in re.findall(r'[-+]?\d+\.\d+(?:[eE][-+]?\d+)?', m.group(1))]
assert len(half) == 48, len(half)
dd = open(os.path.join(D, 'decdata.c'), encoding='latin-1').read()
m = re.search(r'tns_max_bands_tbl\[\(1<<LEN_SAMP_IDX\)\]\[4\]\s*=\s*\{(.*?)\};', dd, re.S)
rows = re.findall(r'\{\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*\}', m.group(1))[:12]
assert len(rows) == 12
notice = open(os.path.join(ROOT, 'third_party/iso14496-5/NOTICE'), encoding='utf-8').read().split('follows verbatim.\n', 1)[1].strip()
notice = notice[2:].strip() if notice.startswith('/*') else notice                      # the delimiters of the original comment would end ours
notice = notice[:-2].rstrip() if notice.endswith('*/') else notice
out = ['/* GENERATED by tools/gen_aac_ssr_tables.py from the ISO/IEC 14496-5 reference software (C050470e_Electronic_inserts, aacErrRobTrans/gc_pqf_common.c and decdata.c) - do not edit.',
       ' * Provenance and licence: third_party/iso14496-5/NOTICE and docs/BIBLIOTEKA_PLAN.md.  The licence notice of the software module is repeated here as it requires:', ' *', *[' * ' + l for l in notice.split('\n')], ' */',
       '#include "sauti_aac_ssr.h"', '',
       '/* the first half (48 of 96) of the prototype filter of the 4-band polyphase quadrature filter bank, symmetric: p[95 - j] = p[j] (gc_pqf_common.c: a_half) */',
       'const double sauti_aac_ssr_pqf_half[48] = {']
for i in range(0, 48, 3): out.append('    ' + ', '.join(half[i:i + 3]) + ',')
out += ['};', '', '/* TNS_MAX_BANDS of the SSR profile per sampling_frequency_index 0..11: long window, short window (decdata.c: tns_max_bands_tbl columns 3 and 4) */',
        'const uint8_t sauti_aac_ssr_tns_max_bands[12][2] = {']
for r in rows: out.append('    { %s, %s },' % (r[2], r[3]))
out.append('};')
open(os.path.join(ROOT, 'src/decoders/modern/aac/sauti_aac_ssr_tables.c'), 'w').write('\n'.join(out) + '\n')
print('written', len(half), 'coefficients and', len(rows), 'TNS rows')
